        "minimum": 0,
        "type": "integer"
       }
      },
      "required": [
       "bps",
       "fixed_minor"
      ],
      "type": "object"
     },
     "other": {
      "additionalProperties": false,
      "properties": {
       "bps": {
        "minimum": 0,
        "type": "integer"
       },
       "fixed_minor": {
        "minimum": 0,
        "type": "integer"
       }
      },
      "required": [
       "bps",
       "fixed_minor"
      ],
      "type": "object"
     }
    },
    "required": [
     "eea_consumer",
     "other"
    ],
    "type": "object"
   }
  },
  "required": [
   "segments",
   "failed_attempts"
  ],
  "type": "object"
 },
 "chargeback_fee": {
  "properties": {
   "amount_minor": {
    "minimum": 0,
    "type": "integer"
   }
  },
  "required": [
   "amount_minor"
  ],
  "type": "object"
 },
 "fx_spread_cap": {
  "properties": {
   "benchmark": {
    "const": "fx_mid_hourly"
   },
   "caps_bps": {
    "additionalProperties": {
     "minimum": 0,
     "type": "integer"
    },
    "minProperties": 1,
    "propertyNames": {
     "enum": [
      "GBP",
      "USD",
      "CHF",
      "PLN"
     ]
    },
    "type": "object"
   },
   "rate_time": {
    "const": "execution_hour"
   }
  },
  "required": [
   "benchmark",
   "rate_time",
   "caps_bps"
  ],
  "type": "object"
 },
 "markup_bps_tiered": {
  "properties": {
   "basis": {
    "const": "monthly_processed_volume"
   },
   "tiering": {
    "const": "retroactive"
   },
   "tiers": {
    "items": {
     "additionalProperties": false,
     "properties": {
      "bps": {
       "minimum": 0,
       "type": "integer"
      },
      "up_to_minor": {
       "minimum": 0,
       "type": [
        "integer",
        "null"
       ]
      }
     },
     "required": [
      "up_to_minor",
      "bps"
     ],
     "type": "object"
    },
    "minItems": 1,
    "type": "array"
   }
  },
  "required": [
   "basis",
   "tiering",
   "tiers"
  ],
  "type": "object"
 },
 "monthly_minimum": {
  "properties": {
   "amount_minor": {
    "minimum": 0,
    "type": "integer"
   },
   "applies_to": {
    "const": "markup"
   }
  },
  "required": [
   "applies_to",
   "amount_minor"
  ],
  "type": "object"
 },
 "pass_through": {
  "properties": {
   "components": {
    "items": false,
    "minItems": 2,
    "prefixItems": [
     {
      "const": "interchange"
     },
     {
      "const": "scheme_fee"
     }
    ],
    "type": "array"
   },
   "reference": {
    "minLength": 1,
    "type": "string"
   }
  },
  "required": [
   "components",
   "reference"
  ],
  "type": "object"
 },
 "payout_fee": {
  "oneOf": [
   {
    "not": {
