        "min_minor"
       ]
      },
      {
       "required": [
        "cap_minor"
       ]
      }
     ]
    },
    "required": [
     "fixed_minor"
    ]
   },
   {
    "not": {
     "required": [
      "fixed_minor"
     ]
    },
    "required": [
     "bps",
     "min_minor",
     "cap_minor"
    ]
   }
  ],
  "properties": {
